      "category": "embedding_representation",
      "rationale": "Apply smooth row-norm compression e/sqrt(1+||e||²/d) to the shared input and output item embeddings across all four datasets. This may reduce domination by large-norm items while preserving embedding dimensions, tying, GRU topology, scoring, loss and optimizer. The generated predictor imports the modified model class, so it uses identical normalization without checkpoint changes.",
      "edits": [
        {
          "find": "    def aggregate_states(self, out: torch.Tensor, seq: torch.Tensor) -> torch.Tensor:",
          "replace": "    def item_embeddings(self, items: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(items)\n        return emb * torch.rsqrt(1.0 + emb.square().mean(dim=-1, keepdim=True))\n\n    def aggregate_states(self, out: torch.Tensor, seq: torch.Tensor) -> torch.Tensor:"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_embeddings(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))\n        out, _ = self.gru(emb)\n        out = self.aggregate_states(out, seq)\n        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.item_emb(neg)).sum(dim=-1)\n        return pos_scores, neg_scores",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_embeddings(seq))\n        out, _ = self.gru(emb)\n        out = self.aggregate_states(out, seq)\n        pos_scores = (out * self.item_embeddings(pos)).sum(dim=-1)\n        neg_scores = (out * self.item_embeddings(neg)).sum(dim=-1)\n        return pos_scores, neg_scores"
        },
